package com.bank.pk.repository;

import com.bank.pk.model.Account;
import org.springframework.data.jpa.repository.JpaRepository;
import java.util.List;
import java.util.Optional;

public interface AccountRepository extends JpaRepository<Account, String> {
    // findById is inherited → unique clustered PK lookup, at most 1 row, no sort
    // Range on the PK → contiguous clustered read, no extra sort
    List<Account> findByIdBetweenOrderById(String fromId, String toId);
    // Non-PK lookup → secondary index ix_accounts_email + bookmark hop
    Optional<Account> findByEmail(String email);
}
