package com.bank.pk.service;

import com.bank.pk.model.Account;
import com.bank.pk.repository.AccountRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.util.List;
import java.util.Optional;

@Service
public class AccountLookupService {
    private static final Logger log = LoggerFactory.getLogger(AccountLookupService.class);
    private final AccountRepository repo;

    public AccountLookupService(AccountRepository repo) { this.repo = repo; }

    public Optional<Account> byPrimaryKey(String id) {
        log.info("PK lookup {}: unique clustered B-tree, 1 traversal, stops at first match", id);
        return repo.findById(id);
    }

    public List<Account> byPrimaryKeyRange(String fromId, String toId) {
        log.info("PK range {}..{}: clustered sorted read, no extra sort", fromId, toId);
        return repo.findByIdBetweenOrderById(fromId, toId);
    }

    public Optional<Account> byEmail(String email) {
        log.info("Non-PK email lookup: secondary index seek + bookmark hop (2 traversals)");
        return repo.findByEmail(email);
    }
}
